jQuery(document).ready(function(e){e("#linked_store").select2({ajax:{url:multivendorx.ajaxurl,dataType:"json",delay:250,data:function(e){return{term:e.term,action:"multivendorx_search_stores",nonce:multivendorx.nonce}},processResults:function(e){return{results:e}}},minimumInputLength:3,placeholder:multivendorx.select_text,allowClear:!0})});